-- 축제장 안의 장소(낚시터·체험장·먹거리·안내). 지도에 표시하고, 현장 관리 화면에서 추가·수정·삭제할 수 있다.
create table festival_place (
    id           bigint generated by default as identity primary key,
    name         varchar(60)  not null,
    category     varchar(20)  not null,
    description  varchar(300),
    fee          varchar(200),
    lat          double precision not null,
    lng          double precision not null,
    coord_source varchar(120) not null,
    info_source  varchar(200) not null,
    sort_order   integer      not null default 100,
    updated_at   timestamp with time zone not null
);

-- 출처: 재단법인 나라 2026 산천어축제 「행사장 안내도」·「산천어축제 체험료」 (2027 업데이트 예정)
-- 좌표: 행사장 안내도(그림)를 OSM 건물 7곳에 맞춰 옮긴 근사값(오차 약 100m)
